SELECT txn_type, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END), 0), 2) AS amount_per_refund, SIZE(COLLECT_SET(merchant)) AS num_merchants, COUNT(DISTINCT id) AS distinct_ids, PERCENT_RANK() OVER (PARTITION BY txn_type ORDER BY ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END), 0), 2) DESC) AS amount_per_refund_percent_rank FROM transactions GROUP BY txn_type, quarter_start ORDER BY quarter_start NULLS FIRST
